// her colours: hologram blue with black lines
const FILL = '#bfe6ff', INK = '#05070f';
// one size for every pose: her idle pose is 74 sprite units tall (the pixel Nova's height)
const K = 74 / (POSES.idle.body[3] - POSES.idle.body[1]);
// the canvas is a little bigger than the pixel sprite's, for her hair, wide poses and sitting
// (she sits with her knees up, so her head is higher than the pixel Nova's)
const PAD = { x: 18, top: 28 };
// the sheet draws her walk a little smaller than her idle; this keeps her the same size
const SIZE = { walk1: 1.1, walk2: 1.1, walk3: 1.1, walk4: 1.1 };
// where each pose stands in the pixel sprite's 48 x 80 box: [centre x, y of her lowest point]
// (the fall is centred instead)
const PLACE = { sit: 48, fall: 'centre' };
// which pose each animation uses, frame by frame (moves the sheet doesn't have use the nearest one)
const ANIM = {
  walk: ['walk1', 'walk2', 'walk3', 'walk4'], run: ['walk1', 'walk2', 'walk3', 'walk4'], carry: ['walk1', 'walk2', 'walk3', 'walk4'], folder: ['walk1', 'walk2', 'walk3', 'walk4'],
  wave: ['wave'], cheer: ['wave'], dance: ['wave', 'idle'], sit: ['sit'], sleep: ['sleep'], fall: ['fall'], dangle: ['fall'],
};
const poseFor = (anim, frame) => { const list = ANIM[anim] || ['idle']; return list[((frame % list.length) + list.length) % list.length]; };

const cache = new Map();
function frameCanvas(name, scale, flip) {
  const key = name + '|' + scale + '|' + flip;
  if (cache.has(key)) return cache.get(key);
  const p = POSES[name], [bx0, by0, bx1, by1] = p.body;
  const w = (48 + PAD.x * 2) * scale, h = (80 + PAD.top) * scale;
  const c = (typeof OffscreenCanvas !== 'undefined') ? new OffscreenCanvas(w, h) : Object.assign(document.createElement('canvas'), { width: w, height: h });
  const g = c.getContext('2d');
  // place her: centred across, her lowest point on the ground (or the window she sits on)
  const k = K * (SIZE[name] || 1), cx = (bx0 + bx1) / 2, place = PLACE[name];
  const ty = place === 'centre' ? 42 - ((by0 + by1) / 2) * k : (place || 78) - by1 * k;
  g.save();
  if (flip) { g.translate(w, 0); g.scale(-1, 1); }
  g.scale(scale, scale);
  g.translate(PAD.x + 24 - cx * k, PAD.top + ty);
  g.scale(k, k);
  g.fillStyle = FILL; g.fill(new Path2D(p.fill));
  g.fillStyle = INK; g.fill(new Path2D(p.ink));
  g.restore();
  if (cache.size > 80) cache.clear();
  cache.set(key, c);
  return c;
}

// frame packs: animations drawn frame by frame by the artist (src/frames, made by
// art/frames/make_packs.py). An animation with a pack plays its frames; the rest use the poses above.
const PACKS = root.NovaFramePacks || {};
const images = {};
function packFrames(anim) {
  const p = PACKS[anim];
  if (!p || typeof Image === 'undefined') return null;
  if (!images[anim]) images[anim] = p.frames.map(f => Object.assign(new Image(), { src: f.src }));
  return images[anim].every(im => im.complete && im.naturalWidth) ? images[anim] : null;   // (the poses fill in while they load)
}
function packInfo(anim) {
  const p = PACKS[anim];
  if (!p) return null;
  const info = { frames: p.frames.length, loop: p.loop, fps: p.fps || 1000 / p.durations[0] };
  for (const k of ['durations', 'loopFrom', 'speed', 'grip']) if (p[k] !== undefined) info[k] = p[k];
  return info;
}
